template:
struct Request { url: String, timeout: u64 }
struct Builder { url: String, timeout: u64 }

impl Builder {
    fn new(u: &str) -> Self {
        Self { url: u.to_string(), timeout: 30 }
    }
    fn timeout(⟦self_param⟧, t: u64) -> ⟦ret_type⟧ {
        self.timeout = t;
        self
    }
    fn build(self) -> Request {
        Request { url: self.url, timeout: self.timeout }
    }
}

fn main() {
    let r = Builder::new("a").timeout(60).build();
    assert_eq!(r.timeout, 60);
}
